import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Plan — FR 3.2.3: Sign In with Google OAuth","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-3-sign-in-with-google-oauth/plan.md","filePath":"feature/srs/01-authentication/3-2-3-sign-in-with-google-oauth/plan.md"}'),c={name:"feature/srs/01-authentication/3-2-3-sign-in-with-google-oauth/plan.md"};function r(i,e,n,l,s,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-3-sign-in-with-google-oauth" tabindex="-1">Plan — FR 3.2.3: Sign In with Google OAuth <a class="header-anchor" href="#plan-—-fr-3-2-3-sign-in-with-google-oauth" aria-label="Permalink to &quot;Plan — FR 3.2.3: Sign In with Google OAuth&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Backend-driven Google OAuth 2.0 authorization-code flow, CSRF state verification, case-insensitive account linking (<code>BR-01</code>), lifecycle checks (<code>BR-05</code>), and 2FA challenge support.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (public routes <code>/api/v1/auth/oauth/google/**</code> and callback alias <code>/login/oauth2/code/google</code>)</td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/GoogleOAuthController.java</code> (<code>redirect</code>, <code>callback</code>, plus authenticated <code>link</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/GoogleOAuthService.java</code> (<code>fetchProfile</code> via <code>APPLICATION_FORM_URLENCODED</code>), <code>OAuthService.java</code>, <code>AuthServiceImpl.java</code></td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>model/auth/UserOAuthProvider.java</code>, <code>UserOAuthProviderRepository.java</code>, <code>UserRepository.java</code>, Redis <code>oauth:state:{state}</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/auth/OAuthCallbackPage.tsx</code>, <code>src/pages/auth/hooks/useOAuthCallback.ts</code>, <code>src/pages/auth/LoginPage.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>app/(auth)/login.tsx</code>, <code>src/services/authService.ts</code></td></tr></tbody></table><h2 id="_2-resolved-engineering-defect-form-encoded-token-exchange" tabindex="-1">2. Resolved Engineering Defect &amp; Form-Encoded Token Exchange <a class="header-anchor" href="#_2-resolved-engineering-defect-form-encoded-token-exchange" aria-label="Permalink to &quot;2. Resolved Engineering Defect &amp; Form-Encoded Token Exchange&quot;">​</a></h2><ul><li><strong>Root Cause Fixed:</strong> <code>GoogleOAuthService.fetchProfile()</code> previously posted a JSON <code>Map.of(...)</code> body to <code>https://oauth2.googleapis.com/token</code>, which Google OAuth rejects because RFC 6749 requires <code>application/x-www-form-urlencoded</code>.</li><li><strong>Implementation Fix:</strong> Switched token exchange payload to <code>LinkedMultiValueMap&lt;String, String&gt;</code> with explicit <code>.contentType(MediaType.APPLICATION_FORM_URLENCODED)</code>, followed by <code>GET https://www.googleapis.com/oauth2/v2/userinfo</code> validating <code>verified_email == true</code>.</li></ul><h2 id="_3-database-redis-schema" tabindex="-1">3. Database &amp; Redis Schema <a class="header-anchor" href="#_3-database-redis-schema" aria-label="Permalink to &quot;3. Database &amp; Redis Schema&quot;">​</a></h2><ul><li><strong>PostgreSQL <code>user_oauth_providers</code>:</strong> <code>id</code> (<code>UUID</code>), <code>user_id</code> (<code>UUID</code> FK -&gt; <code>users.id</code>), <code>provider</code> (<code>OAuthProvider.GOOGLE</code>), <code>provider_user_id</code> (<code>VARCHAR</code>, Google <code>sub</code>/<code>id</code>), <code>email</code>, <code>created_at</code> — <code>UNIQUE(provider, provider_user_id)</code>.</li><li><strong>PostgreSQL <code>users</code>:</strong> Auto-provisioned OAuth users have <code>email_verified_at = now</code>, <code>password_hash = null</code>, <code>full_name</code> and <code>avatar_url</code> populated from Google profile, and default <code>SystemRole.USER</code>.</li><li><strong>Redis CSRF State:</strong> <code>oauth:state:{state}</code> (cryptographically random token, single-use atomic read-and-delete, 5-minute TTL).</li></ul><h2 id="_4-end-to-end-execution-flow" tabindex="-1">4. End-to-End Execution Flow <a class="header-anchor" href="#_4-end-to-end-execution-flow" aria-label="Permalink to &quot;4. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Consent Redirect (<code>GET /api/v1/auth/oauth/google</code>):</strong> Generates random <code>state</code>, stores <code>oauth:state:{state}</code> in Redis, and returns <code>302 Found</code> to Google&#39;s OAuth 2.0 consent endpoint.</li><li><strong>Callback Verification (<code>GET /api/v1/auth/oauth/google/callback</code> or <code>/login/oauth2/code/google</code>):</strong><ul><li>Atomically consumes <code>oauth:state:{state}</code> from Redis; missing/expired state or provider <code>error</code> parameter redirects safely to <code>/login?error=oauth_failed</code>.</li><li>Exchanges authorization <code>code</code> via <code>APPLICATION_FORM_URLENCODED</code> POST and fetches verified Google user profile (<code>email</code>, <code>name</code>, <code>picture</code>).</li></ul></li><li><strong>Case-Insensitive Account Merge or Auto-Provision (<code>BR-01</code>, <code>BR-05</code>):</strong><ul><li>Normalizes email (<code>lowercase + trim</code>). If <code>User</code> exists, links <code>UserOAuthProvider(GOOGLE)</code> if not yet linked; otherwise creates <code>User</code> (<code>ACTIVE</code>, <code>emailVerifiedAt = now</code>, <code>passwordHash = null</code>) + <code>UserSystemRole(USER)</code> + <code>UserOAuthProvider</code>.</li><li>Enforces <code>checkStatus(user)</code> (<code>DEACTIVATED</code> / <code>SUSPENDED</code> redirect with error code).</li></ul></li><li><strong>2FA Handoff vs Token Fragment Redirect:</strong><ul><li>If <code>user.isTwoFactorEnabled()</code> is <code>true</code>: generates 5-minute <code>twoFactorToken</code> and redirects <code>302</code> to <code>/2fa-verify?twoFactorToken=...</code> (reusing <code>POST /api/v1/auth/2fa/verify</code>).</li><li>Otherwise: sets <code>HttpOnly</code> <code>refreshToken</code> cookie, writes <code>AuditLog(LOGIN)</code>, and redirects <code>302</code> to <code>/oauth/callback#token=&lt;accessToken&gt;</code>, where <code>useOAuthCallback.ts</code> extracts the fragment, clears URL history, loads <code>/users/me</code>, and routes into the app.</li></ul></li></ol><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.3</code> — Sign In with Google OAuth</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>GET /api/v1/auth/oauth/google · GET /api/v1/auth/oauth/google/callback · GET /login/oauth2/code/google</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>GoogleOAuthController</code> -&gt; <code>GoogleOAuthService, OAuthService, AuthServiceImpl</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code>, <code>user_oauth_providers</code>, <code>audit_logs</code>; Redis <code>oauth:state:{state}</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-01, BR-05</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>302 ?error=oauth_failed</code> / <code>ACCOUNT_DEACTIVATED</code> / <code>ACCOUNT_SUSPENDED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/auth/LoginPage.tsx</code>, <code>src/pages/auth/OAuthCallbackPage.tsx</code>, <code>src/pages/auth/hooks/useOAuthCallback.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>app/(auth)/login.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>auth.oauth.* / auth.login.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',15)])])}const p=t(c,[["render",r]]);export{u as __pageData,p as default};
